#!/bin/sh
# every suite against PAGE/SERVER (default: the published pair), one line a suite and the full logs in tests/logs/: sh tests/all.sh [prefix]
# SUITES="relay online" picks some; PORT_T is the port of the online ones; the old-server suites need SERVER=<an old server.js> and are not in the list,
# nor are the long ones (soak, transport-battle). The quick ones come first; loadout*, transport, field, world and bases take minutes each
cd "$(dirname "$0")/.." && mkdir -p tests/logs
for t in ${SUITES:-sim-split map-tags hud-labels town-names pack-cut hud-start hud-decimal som sides3-start sides3-online mcp-sides3 relay crew-relay damage-relay drone-relay forts-relay gen-relay resume-relay heli-relay transport-relay sappers-relay pad ana ana-man ana-mano-net ana-parado damage heli heli-arms heli-ai crew infantry folego squads pop-push mission production smoke-sight perception brain-honesty missiles missile-los gbu-lock drone woods forts sappers posts aid city seat cover loadout loadout-more loadout-stores transport field world bases online crew-online drone-online forts-online sappers-online heli-online world-online cover-online bases-online loadout-online transport-online city-online eco-online gen-online resume-online ana-online frame-budget clock sky-relay sky sky-online help-relay help drills brain brain-lider brain-pelotao brain-falas comms-relay comms radio radio-general logistics-relay logistics logistics-online civ civ-war civ-online rec-relay rec rec-online orders-relay orders orders-online bridges-relay road-mesh bomber-run bridges bridges-build bridges-online campaign-relay campaign personality-relay personality vet w13 w13-online tmap-relay tmap ambush approaches-relay approaches procedures afp veh-drills brain-drills gfx veg-fade sparks-light water-shore road-look ram fluxos rematch sides3 state-gc}; do
  [ -f tests/$t.js ] || continue
  s=$(date +%s); node tests/$t.js > tests/logs/$1$t.log 2>&1; rc=$?
  echo "$t rc=$rc $(( $(date +%s) - s ))s $(tail -1 tests/logs/$1$t.log)"
done
